class Solution {
public:
    vector<string> res;
    void backtrack(string digits, int idx, string curr, vector<string>& letters) {
        if (idx == digits.size()) {
            res.push_back(curr);
            return;
        }
        for (auto c : letters[digits[idx] - '0']) {
            curr.push_back(c);
            backtrack(digits, idx + 1, curr, letters);
            curr.pop_back();
        }
    }
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) {
            return {};
        }
        vector<string> letters = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        backtrack(digits, 0, "", letters);
        return res;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    int countnode(ListNode* head) {
        int res = 0;
        while (head) {
            res++;
            head = head->next;
        }
        return res;
    }
    ListNode* removeNthFromEnd(ListNode* head, int k) {

        ListNode* cnd = head;
        int n = countnode(cnd);
        if (k == n)
            return head->next;
        int stk = n - k - 1; // stop before prevoius node
        auto it = head;
        while (stk > 0) {
            it = it->next;
            stk--;
        }
        it->next = it->next->next; // skip k th node

        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {

        ListNode* nwhead = new ListNode(-1);
        ListNode* go = nwhead;

        while (list1 && list2) {
            if (list1->val < list2->val) {
                go->next = list1;
                list1 = list1->next;
            } else {
                go->next = list2;
                list2 = list2->next;
            }
            go = go->next;
        }

        while (list1) {
            go->next = list1;
            go = go->next;
            list1 = list1->next;
        }

        while (list2) {
            go->next = list2;
            go = go->next;
            list2 = list2->next;
        }

        return nwhead->next;
    }
};

