/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        if (!head || k == 1) return head; // Edge case: If k=1, no need to reverse

        ListNode dummy(0); // Dummy node to handle head changes
        dummy.next = head;
        ListNode *prevGroupEnd = &dummy;

        while (true) {
            // Find the kth node
            ListNode* kthNode = prevGroupEnd;
            for (int i = 0; i < k; i++) {
                kthNode = kthNode->next;
                if (!kthNode) return dummy.next; // If less than k nodes remain, return result
            }

            // Reverse k nodes
            ListNode* prev = kthNode->next;
            ListNode* curr = prevGroupEnd->next;
            ListNode* nextNode;

            for (int i = 0; i < k; i++) {
                nextNode = curr->next;
                curr->next = prev;
                prev = curr;
                curr = nextNode;
            }

            // Connect with previous part
            ListNode* temp = prevGroupEnd->next;
            prevGroupEnd->next = kthNode;
            prevGroupEnd = temp;
        }
    }
};

class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        int breakidx = -1;

        // Find the first number that is smaller than the next one, starting from the end
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] < nums[i + 1]) {
                breakidx = i;
                break;
            }
        }

        // If no such number exists, the array is in descending order, reverse it
        if (breakidx == -1) {
            reverse(nums.begin(), nums.end());
            return;
        }

        // Find the smallest number that is larger than nums[breakidx] from the end
        for (int i = n - 1; i > breakidx; i--) {
            if (nums[i] > nums[breakidx]) {
                swap(nums[i], nums[breakidx]);
                break;
            }
        }

        // Reverse the elements after breakidx to get the smallest next permutation
        sort(nums.begin() + breakidx + 1, nums.end());
    }
};

class Solution {
public:
    int search(vector<int>& nums, int t) {
        int n=nums.size();
        int lw=0,hi=n-1;
        while(lw<=hi){
            int md=(lw+hi)/2;

            if(nums[md]==t){
                return md;
            }
            if(nums[lw]<=nums[md]){
                if(nums[lw]<=t && t<=nums[md]){
                    hi=md-1;
                }else{
                    lw=lw+1;
                }
            }
            else{
                if(nums[md]<=t && t<=nums[hi]){
                    lw=md+1;
                }else{
                    hi=md-1;
                }
            }
        }
        return -1;
    }
};

class Solution {
public:
    int searchInsert(vector<int>& nums, int target) {
      int  len =nums.size();
        if (target > nums[len - 1]) {
            return len;
        }
        int left = 0, right = len - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                return mid;
            } else if (nums[mid] > target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        // here left == right, you can return either one
        return right;
    }
};

