        if (can[idx] <= s) {
            in.push_back(can[idx]);
            call(can, idx , in, s - can[idx]);
            in.pop_back();
        }

        call(can, idx - 1, in, s);
    }
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        int n = candidates.size();
        vector<int> in;
        call(candidates, n - 1, in, target);
        return res;
    }
};

