        res = []
        cur = []
        def go(start, remain):
            if remain == 0:
                res.append(cur[:])
                return
            for i in range(start, len(candidates)):
                if candidates[i] > remain:
                    continue
                cur.append(candidates[i])
                go(i, remain - candidates[i])
                cur.pop()
        go(0, target)
        return res

