class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int t) {
      int row=matrix.size(),col=matrix[0].size();
      int rw=0,cl=col-1;
      while(rw<row && cl>=0){
            int vl =matrix[rw][cl];
            if(vl==t){
                return 1;
            }
            if(vl>t){
              cl--;
            }else if(vl<t){
              rw++;
            }
      }
      return 0; 
    }
};

class Solution {
public:
    void sortColors(vector<int>& nums) {
        int n = nums.size();
        int p2 = n - 1, p1, p0 = 0;

        for (int i = 0; i <= p2; i++) {
            if (nums[i] == 0) {
                swap(nums[i], nums[p0]);
                p0++;
            } else if (nums[i] == 2) {
                swap(nums[i], nums[p2]);
                i--;
                p2--;
            }
        }

    }
};

class Solution {
public:
    bool isHave(int i, int j, int l, vector<vector<char>>& board, string& word,
                vector<vector<int>>& vis) {
        int n = board.size(), m = board[0].size();
        if (i < 0 || j < 0 || i >= n || j >= m || vis[i][j] == 1 ||
            board[i][j] != word[l]) {
            return false;
        }
        if (l == word.size() - 1) {
            return true;
        }
        vis[i][j] = 1;
        int dx[4] = {-1, 1, 0, 0};
        int dy[4] = {0, 0, -1, 1};
        for (int c = 0; c < 4; c++) {
            int nx = i + dx[c], ny = j + dy[c];
            if (isHave(nx, ny, l + 1, board, word, vis)) {
                return true;
            }
        }

        // Backtrack: unmark the current cell
        vis[i][j] = 0;
        return false;
    }

    bool exist(vector<vector<char>>& board, string word) {
        int n = board.size(), m = board[0].size();
        vector<vector<int>> vis(n, vector<int>(m, 0));

        // Start DFS from every cell
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == word[0] &&
                    isHave(i, j, 0, board, word, vis)) {
                    return true;
                }
            }
        }
        return false;
    }
};

