/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
public:
    bool call(TreeNode* left, TreeNode* right) {
        if(!right && !left){
            return true;
        }
        if (!right || !left) {
            return false;
        }
        if (left->val != right->val) {
            return false;
        }

        return (call(left->left, right->right) && call(left->right, right->left));
    }
    bool isSymmetric(TreeNode* root) { return call(root, root); }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
        if (root == NULL) {
            return {};
        }

        queue<TreeNode*> q;
        q.push(root);
        vector<vector<int>> res;
        int level = 0;
        while (!q.empty()) {
            int n = q.size();
            vector<int> in;
            for (int i = 0; i < n; i++) {
                auto it = q.front();
                q.pop();
                in.push_back(it->val);

                if (it->left) {
                    q.push(it->left);
                }
                if (it->right) {
                    q.push(it->right);
                }
            }

            if (level % 2 != 0) {
                reverse(in.begin(), in.end());
            }
            level++;
            res.push_back(in);
        }
        return res;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
int call(TreeNode* root){
    if(root==NULL){
        return 0;
    }
    int left = call(root->left);
        if (left == -1) return -1;  // left subtree not balanced

        int right = call(root->right);
        if (right == -1) return -1; // right subtree not balanced

    if(abs(left-right)>1){
        return -1;
    }

    return max(left, right)+1;
}
    bool isBalanced(TreeNode* root) {
        if(root==NULL){
            return 1;
        }
        return call(root)!=-1;
    }
};

