class Solution {
public:
    vector<vector<string>> res;
    bool isPalidrome(string s, int l, int r) {
        while (l < r) {
            if (s[l] != s[r]) {
                return false;
            }
            l++;
            r--;
        }
        return true;
    }
    void call(int idx, string s, vector<string>& in) {
        if (idx >= s.size()) {
            res.push_back(in);
            return;
        }
        for (int i = idx; i < s.size(); i++) {
            if (isPalidrome(s, idx, i)) {
                in.push_back(s.substr(idx, i - idx + 1));
                call(i + 1, s, in);
                in.pop_back();
            }
        }
    }
    vector<vector<string>> partition(string s) {
        vector<string> in;
        call(0, s, in);
        return res;
    }
};

class Solution {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
         int total_gas = 0, total_cost = 0, tank = 0, start = 0;

    // Step 1: Calculate total gas and total cost
    for (int i = 0; i < gas.size(); i++) {
        total_gas += gas[i];
        total_cost += cost[i];
    }

    // Step 2: Check if the trip is possible
    if (total_gas < total_cost) {
        return -1;
    }

    // Step 3: Find the starting station
    for (int i = 0; i < gas.size(); i++) {
        tank += gas[i] - cost[i];
        if (tank < 0) { // If tank is negative, reset start and tank
            start = i + 1;
            tank = 0;
        }
    }

    return start;
    }
};

class Solution {
public:
    int evalRPN(vector<string>& tokens) {
        stack<int> st;

        for (auto it : tokens) {
            if (it == "+" || it == "-" || it == "*" || it == "/") {
                int n1 = st.top(); st.pop();
                int n2 = st.top(); st.pop();

                if (it == "+") st.push(n2 + n1);
                else if (it == "-") st.push(n2 - n1);
                else if (it == "*") st.push(n2 * n1);
                else st.push(n2 / n1);  

            } else {
                st.push(stoi(it));  
            }
        }

        return st.top();
    }
};

class Solution {
public:
        string reverseWords(const string_view s) {
        // Breakup the input into words and put them on a stack.
        stack<string_view> st;
        size_t start = 0;
        size_t end = 0;
        while ((start = s.find_first_not_of(' ', end)) != string::npos) {
            end = s.find_first_of(' ', start);
            st.push(s.substr(start, end - start));
        }
        // Stitch the answer together.
        string ans;
        ans.reserve(size(s));
        while (!empty(st)) {
            if (!empty(ans)) ans.push_back(' ');
            ans += st.top();
            st.pop();
        }
        return ans;
    }
};

