    vector<int> largestDivisibleSubset(vector<int>& nums) {
        // Step 1: Sort the input array to ensure divisibility conditions are
        sort(nums.begin(), nums.end());
        int n = nums.size();

        // Step 2: Initialize DP and parent arrays
        vector<int> dp(n, 1);
        // dp[i] stores the size of the largest subset ending at i
        vector<int> parent(n, -1); // parent[i] helps reconstruct the subset
        int maxSize = 0;           // To track the size of the largest subset
        int maxIndex = -1; // To track the ending index of the largest subset

        // Step 3: Fill the DP and parent arrays
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                // Check if nums[i] is divisible by nums[j]
                if (nums[i] % nums[j] == 0 && dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1; // Update the size of the subset
                    parent[i] = j;
                    // Update the parent to reconstruct the subset
                }
            }

            // Update the largest subset size and its ending index
            if (dp[i] > maxSize) {
                maxSize = dp[i];
                maxIndex = i;
            }
        }

        // Step 4: Reconstruct the largest subset
        vector<int> result;
        while (maxIndex != -1) {
            result.push_back(nums[maxIndex]);
            // Add the current element to the result
            maxIndex = parent[maxIndex]; // Move to the parent
        }

        reverse(result.begin(), result.end());
        // Reverse to get the correct order
        return result;
    }
};

class Solution {
public:
    vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) { // time complexity is O(m*nlogk), m = nums1 size, n = nums2 size
        priority_queue<pair<int,pair<int,int>>> pq;  // default: the greatest comes top
        for(int i=0;i<nums1.size();i++) {
            for(int j=0;j<nums2.size();j++) {
                int sum=nums1[i]+nums2[j];
                if (pq.size()<k) {
                    pq.push({sum,{nums1[i],nums2[j]}});
                }
                else if (sum<pq.top().first) {
                    pq.pop();
                    pq.push({sum,{nums1[i],nums2[j]}});
                } else {
                    break; 
                 // save time! since we don't need to traverse the rest of vector 2
                }
            }
        }
        vector<vector<int>> ans;
        while(!pq.empty()) {
            ans.push_back({pq.top().second.first, pq.top().second.second});
            pq.pop();
        }
        reverse(ans.begin(),ans.end());
        return ans;
    }
};

class Solution {
public:
    int countLessEqual(vector<vector<int>>& matrix, int mid, int n) {
        int count = 0, row = n - 1, col = 0;

        while (row >= 0 && col < n) {
            if (matrix[row][col] <= mid) {
                count += (row + 1); // all elements above are ≤ mid
                col++;
            } else {
                row--;
            }
        }
        return count;
    }

    int kthSmallest(vector<vector<int>>& matrix, int k) {
        int n = matrix.size();
        int low = matrix[0][0], high = matrix[n - 1][n - 1];

        while (low < high) {
            int mid = low + (high - low) / 2;
            int cnt = countLessEqual(matrix, mid, n);
            if (cnt < k) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
};

