            res.push_back(c);
        }

        // Remove remaining `k` digits from the end if needed
        while (k > 0 && !res.empty()) {
            res.pop_back();
            k--;
        }

        // Remove leading zeros
        int i = 0;
        while (i < res.size() && res[i] == '0') i++;
        res = res.substr(i);

        return res.empty() ? "0" : res;
    }
};

