class Solution {
public:
    int findShortestSubArray(vector<int>& nums) {
        unordered_map<int, vector<int>> degree;
        // storing max degree
        int m = 0;
        // storing length of subarray
        int k = nums.size();

        for(int i=0; i<nums.size(); i++) {
            // assign vector of size 2 for every new element
            // 1- degree of the element 2- first position of element
            if(degree.find(nums[i]) == degree.end())
                degree[nums[i]] = vector<int>(2);

            // increment degree of the element and
            // if its first occurred than fill its first position
            if(++degree[nums[i]][0] == 1)
                degree[nums[i]][1] = i;

            // update degree of array and length of subarray when
            // degree of the element is greater
            if(degree[nums[i]][0] > m) {
                m = degree[nums[i]][0];
                k = i - degree[nums[i]][1] + 1;
            }
            // update k when there are elements with same max degree
            else if(degree[nums[i]][0] == m)
                k = min(k, i - degree[nums[i]][1] + 1);
        }
        return k;
    }
};

class Solution {
public:
    bool back(vector<int>& nums, vector<int>& visit, int tar, int currSum,
              int idx, int k) {
        int n = nums.size();
        if (k == 0) {
            return true;
        }

        if (currSum == tar) {
            return back(nums, visit, tar, 0, 0, k - 1);
        }
        for (int j = idx; j < n; j++) {
            if (visit[j] || currSum + nums[j] > tar)
                continue;

            visit[j] = true;
            if (back(nums, visit, tar, currSum + nums[j], j + 1, k))
                return true;
            visit[j] = false;
        }

        return false;
    }
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int sum = accumulate(nums.begin(), nums.end(),0);
        int n = nums.size();
        if (n < k || sum % k != 0)
            return false;

        vector<int> visit(n, 0);
        return back(nums, visit, sum / k, 0, 0, k);
    }
};

class Solution {
public:
int dp[1007][1007];
    int call(string &s1, string &s2, int i, int j) {
        if (i < 0 && j < 0)
            return 0;
        if (i < 0) {
            return (int)s2[j] + call(s1, s2, i, j - 1);
        }
        if (j < 0) {
            return (int)s1[i] + call(s1, s2, i - 1, j);
        }
        if(dp[i][j]!=-1){
            return dp[i][j];
        }
        int ship_i = 0, ship_j = 0;
        if (s1[i] == s2[j])
            return dp[i][j]=call(s1, s2, i - 1, j - 1);
        else
            ship_i = s1[i] + call(s1, s2, i - 1, j);
            ship_j = s2[j] + call(s1, s2, i, j - 1);

        return dp[i][j]=min(ship_i, ship_j);
    }
    int minimumDeleteSum(string s1, string s2) {
        int n = s1.size(), m = s2.size();
        memset(dp,-1, sizeof(dp));
        return call(s1, s2, n - 1, m - 1);
    }
};

