class Solution 
{
public:
    int sumSubarrayMins(vector<int>& n) 
    {
        vector<long> s, sums(n.size(),0);
        long j, res=0, mod = 1000000007;
        for (int i = 0; i < n.size(); ++i)
        {
            while (!s.empty() && n[s.back()] > n[i])
                s.pop_back();
            j = !s.empty() ? s.back() : -1;

            sums[i] = ((j>=0?sums[j]:0) + (i-j)*n[i]) % mod;
            s.push_back(i);
        }

        for (int i = 0; i < sums.size(); ++i)
            res = (res + sums[i]) % mod;
        return res;
    }
};

class Solution {
public:
    int partitionDisjoint(vector<int>& nums) {
        int n = nums.size();
        vector<int> leftmx_prefix(n, 0);
        vector<int> rightmin_sufix(n, 0);


        leftmx_prefix[0] = nums[0];
        for (int i = 1; i < n; i++) {
            leftmx_prefix[i] = max(leftmx_prefix[i - 1], nums[i]);
        }


        rightmin_sufix[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            rightmin_sufix[i] = min(rightmin_sufix[i + 1], nums[i]);
        }


        for (int i = 1; i < n; i++) {  
            if (leftmx_prefix[i - 1] <= rightmin_sufix[i]) {
                return i;  // Return partition index
            }
        }

        return -1; 
    }
};

