class Solution {
public:
    int call(int idx, int n, int k, vector<int>& arr, vector<int>& dp) {
        if (idx == n) {
            return 0;
        }
        if (dp[idx] != -1) {
            return dp[idx];
        }
        int mx = 0, sum = 0, len = 0;
        for (int i = idx; i < min(idx + k, n); i++) {
            len++;
            mx = max(mx, arr[i]);
            sum = mx * len + call(i + 1, n, k, arr, dp);
            dp[idx] = max(dp[idx], sum);
        }
        return dp[idx];
    }

    int maxSumAfterPartitioning(vector<int>& arr, int k) {
        int n = arr.size();
        // vector<int> dp(n, -1);
        // return call(0, n, k, arr, dp);

        vector<int> dp1(n + 1, 0);
        dp1[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            int mx = 0, sum = 0, len = 0, mxi = 0;
            for (int j = i; j < min(i + k, n); j++) {
                len++;
                mx = max(mx, arr[j]);
                sum = mx * len + dp1[j + 1];
                mxi = max(mxi, sum);
            }
            dp1[i] = mxi;
        }
        return dp1[0];
    }
};

class Solution {
public:
    vector<int> rearrangeBarcodes(vector<int>& bac) {
        int n=bac.size();
        if(n==0 || n==1){
            return bac;
        }
        map<int,int>mp;
        for(auto it : bac){
            mp[it]++;
        }
        priority_queue<pair<int,int>>q;
        for(auto it : mp){
            q.push({it.second,it.first});
        }

        vector<int>res;
        while(q.top().first>0){
            auto it1=q.top();
            q.pop();
            res.push_back(it1.second);
            it1.first--;

            auto it2=q.top();
            q.pop();
            if(it2.first>0){
                res.push_back(it2.second);
                it2.first--;
            }

            q.push(it1);
            q.push(it2);
        }
        return res;
    }
};

