    void call_val(TreeNode* root, vector<int>& val) {
        if (root == nullptr) {
            return;
        }
        call_val(root->left, val);
        val.push_back(root->val);
        call_val(root->right, val);
    }

    TreeNode* Tree(vector<int>& arr, int st, int en) {
       if(st>en){
           return NULL;
       }
       int md=(st+en)/2;
       TreeNode* nod=new TreeNode(arr[md]);
       nod->left=Tree(arr,st,md-1);
       nod->right=Tree(arr,md+1,en);

       return nod;
    }

    TreeNode* balanceBST(TreeNode* root) {
        vector<int> val;
        call_val(root, val);
        int n = val.size();
        return Tree(val, 0, n - 1);
    }
};

class Solution {
public:
    int constrainedSubsetSum(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> dp(n, 0);
        deque<int> q;
        int ans = INT_MIN;

        for(int i=0; i<n; i++){
            if(!q.empty() && q.front() < i-k){
                q.pop_front();
            }
            int maxi = dp[q.empty() ? i : q.front()];
            dp[i] = max(nums[i], nums[i] + maxi);
            while(!q.empty() && dp[i] >= dp[q.back()]){
                q.pop_back();
            }
            q.push_back(i);
            ans = max(ans, dp[i]);
        }

        return ans;
    }
};

