        stack<pair<char, int>> st;
        for (char c : s) {
            if (!st.empty() && st.top().first == c) {
                st.top().second++; 
                if (st.top().second == k) {
                    st.pop(); 
                }
            } else {
                st.push({c, 1}); 
            }
