        }

        int comres = 1;
        for (int i = 2; i <= n; i++) {
           long long space = (2 * i - 1);
            long long combinations = (space * (space + 1)) / 2; // Calculate combinations
            comres = (comres * combinations) % mod; // Apply mod after each multiplication
        }
        return comres%mod;
    }
};

