class Solution {
public:
    int call(int i, int s, int n, vector<int>& nums, vector<vector<int>>& memo) {
        if (i == n) {
            if (s == 0) {
                return 0;
            }
            return -1e9;
        }

        if (memo[i][s] != -1) {
            return memo[i][s];
        }

        int tt = nums[i] + call(i + 1, (s + nums[i]) % 3, n, nums, memo);
        int nn = call(i + 1, s, n, nums, memo);

        return memo[i][s] = max(tt, nn);
    }

    int maxSumDivThree(vector<int>& nums) {
        int n = nums.size();
        vector<vector<int>> memo(n, vector<int>(3, -1)); // Memoization table

        return call(0, 0, n, nums, memo);
    }
};

class Solution {
public:
    int n, m;
    unordered_map < int, vector<vector<int>>> dairection = {
                             {1, {{0, -1}, {0, 1}}},  {2, {{-1, 0}, {1, 0}}},
                             {3, {{0, -1}, {1, 0}}},  {4, {{0, 1}, {1, 0}}},
                             {5, {{-1, 0}, {0, -1}}}, {6, {{-1, 0}, {0, 1}}},
    };

    bool calldfs(vector<vector<int>>& grid, int x, int y,
                 vector<vector<bool>>& visit) {
                    if(x==n-1 && y==m-1) return true;
        visit[x][y] = true;
        for (auto& dir : dairection[grid[x][y]]) {
            int nwi = x + dir[0], nwj = y + dir[1];
            if (nwi < 0 || nwi >= n || nwj < 0 || nwj >= m || visit[nwi][nwj])
                continue;

            for (auto& backdir : dairection[grid[nwi][nwj]]) {
                if (nwi + backdir[0] == x && nwj + backdir[1] == y) {
                    if (calldfs(grid, nwi, nwj, visit)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    bool hasValidPath(vector<vector<int>>& grid) {
        n = grid.size();
        m = grid[0].size();
        vector<vector<bool>> visit(n+1, vector<bool>( m+1, false));
        return calldfs(grid, 0, 0, visit);
    }
};

class Solution {
public:
const int mod = 1e9 + 7;
map<pair<int, int>, int> dp;

int cal(int steps, int idx, int n){
     if (steps == 0)
    {
      return idx == 0;
    }
    else if (idx >= n || idx < 0)
    {
      return 0;
    }

    if (dp.find({steps, idx}) != dp.end())
    {
      return dp[{steps, idx}];
    }
    int lef_ttk = cal(steps - 1, idx - 1, n);
    int rig_ttk = cal(steps - 1, idx + 1, n);
    int sty_ttk = cal(steps - 1, idx, n);
    return dp[{steps, idx}] = ((lef_ttk + rig_ttk) % mod + sty_ttk) % mod;
}
    int numWays(int steps, int arrLen) {
        return  cal(steps,0,arrLen); 
    }
};

