        int fs = 0;
        ListNode* l1 = list1, *tc1 = nullptr, *tc2 = nullptr;

        while (l1 != nullptr) {
            if (fs == a - 1) {
                tc1 = l1;
            }
            if (fs == b-1) {
                tc2 = l1->next;
                break; 
            }
            l1 = l1->next;
            fs++;
        }

