class Solution {
public:
    string repeatLimitedString(string s, int k) {
        int n = s.size(), i;
        priority_queue<pair<char, int>> q;
        vector<int> a(26);
        for (auto x : s) {
            a[x - 'a']++;
        }
        for (i = 0; i < 26; i++) {
            if (a[i] > 0) {
                q.push({i + 'a', a[i]});
            }
        }
        string ans = "";
        while (!q.empty()) {
            auto f = q.top();
            q.pop();
            int first_frq = f.second;
            char first_char = f.first;
            if (first_frq > k) {
                for (i = 0; i < k; i++) {
                    ans.push_back(first_char);
                }
                first_frq -= k;
                if (!q.empty()) {
                    auto sec = q.top();
                    char secn_char = sec.first;
                    int secn_frq = sec.second;
                    q.pop();
                    secn_frq--;
                    ans.push_back(secn_char);
                    if (secn_frq > 0) {
                        q.push({secn_char, secn_frq});
                    }
                } else {
                    break;
                }
                q.push({first_char, first_frq});
            } else {
                for (i = 0; i < first_frq; i++) {
                    ans.push_back(first_char);
                }
            }
        }
        return ans;
    }
};

class Solution {
public:
    TreeNode* createBinaryTree(vector<vector<int>>& descriptions) {
        unordered_map<int, TreeNode*> map;
        unordered_set<int> children;

        for (auto& arr : descriptions) {
            int parent = arr[0], child = arr[1], isLeft = arr[2];
            children.insert(child);

            if (map.find(parent) == map.end()) {
                map[parent] = new TreeNode(parent);
            }
            if (map.find(child) == map.end()) {
                map[child] = new TreeNode(child);
            }

            if (isLeft == 1) {
                map[parent]->left = map[child];
            } else {
                map[parent]->right = map[child];
            }
        }

        int root = -1;
        for (auto& arr : descriptions) {
            if (children.find(arr[0]) == children.end()) {
                root = arr[0];
                break;
            }
        }

        return map[root];
    }
};

