        long long int left = 0, right = 0, ans = 0;
        while (right < nums.size()) {
            if (nums[right] == max_num)
                count++;

            while (count >= k) {
                if (nums[left] == max_num)
                    count--;
                left++;
                ans += nums.size() - right;
            }
            right++;
        }

        return ans;
    }
};

