                dp[i][j][0]=(dp[i-1][j][0]+dp[i][j-1][0]-dp[i-1][j-1][0])+(grid[i-1][j-1]=='X');
                dp[i][j][1]=(dp[i-1][j][1]+dp[i][j-1][1]-dp[i-1][j-1][1])+(grid[i-1][j-1]=='Y');

                if(dp[i][j][0]!=0 && dp[i][j][0]==dp[i][j][1]){
                    res++;
                }
            }
        }
        return res;
    }
};

